        for exp in range(0, 20):
            assert bitcount(1 << exp) == 1

    def test_bitcount_all_ones(self):
        """A number of the form 2**k - 1 has exactly k 1-bits."""
        for k in range(1, 20):
            assert bitcount((1 << k) - 1) == k

    def test_bitcount_matches_bin_count(self):
        """bitcount should equal the count of '1' in bin(n)."""
        for n in range(0, 500):
            assert bitcount(n) == bin(n).count("1")

    def test_bitcount_large_number(self):
        """bitcount should handle large integers correctly."""
        n = (1 << 100) - 1
        assert bitcount(n) == 100

    def test_bitcount_returns_int(self):
        """bitcount should return an int."""
        result = bitcount(42)
        assert isinstance(result, int)

